public struct PriceInfo {
    public var coinId: String
    public var usdPrice: Double

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(coinId: String, usdPrice: Double) {
        self.coinId = coinId
        self.usdPrice = usdPrice
    }
}

extension PriceInfo: Equatable, Hashable {
    public static func == (lhs: PriceInfo, rhs: PriceInfo) -> Bool {
        if lhs.coinId != rhs.coinId {
            return false
        }
        if lhs.usdPrice != rhs.usdPrice {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(coinId)
        hasher.combine(usdPrice)
    }
}

