    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PriceError {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        case 1: return .RateLimited
        case 2: return try .Network(
                reason: FfiConverterString.read(from: &buf)
